  const render = () => list.replaceChildren(...(sh.protectedRanges ?? []).map((x, i) => el('option', { value: i }, x.name+' — '+refs(x.ranges)+(rangeIsUnlocked(x, editRangeGrants.get(sh)) ? '' : ' 🔒'))));
