// ───────────────────────── 메뉴 정의 ─────────────────────────
const STANDARD = ['#C00000', '#FF0000', '#FFC000', '#FFFF00', '#92D050', '#00B050', '#00B0F0', '#0070C0', '#002060', '#7030A0'];
/** 색 상자의 테마 색: 통합 문서 테마(배경1 · 텍스트1 · 배경2 · 텍스트2 · 강조1~6)와 엑셀의 밝기 단계 (밝기에 따라 단계가 다름) */
function themeRows() {
  const base = THEME.colors.slice(0, 10).map((c) => String(c).toUpperCase().slice(-6));
  const lum = (h) => { const [r, g, b] = [0, 2, 4].map((k) => parseInt(h.slice(k, k + 2), 16) / 255); return (Math.max(r, g, b) + Math.min(r, g, b)) / 2; };
  const steps = (h) => {
    const l = lum(h);
    if (l <= 0) return [0.5, 0.35, 0.25, 0.15, 0.05];
    if (l >= 1) return [-0.05, -0.15, -0.25, -0.35, -0.5];
    if (l < 0.2) return [0.9, 0.75, 0.5, 0.25, 0.1];
    if (l > 0.8) return [-0.1, -0.25, -0.5, -0.75, -0.9];
    return [0.8, 0.6, 0.4, -0.25, -0.5];
  };
  const rows = [base.map((h) => `#${h}`)];
  for (let k = 0; k < 5; k++) rows.push(base.map((h) => `#${applyTint(h, steps(h)[k])}`));
  return rows;
}

let lastPatternColor = '#000000';
function colorMenu(anchorEl, kind) {
  // 채우기: 엑셀처럼 무늬(패턴) 채우기 · 무늬 색도 바로 고를 수 있게
  const extra = kind !== 'fill' ? [] : (() => {
    const cur = wb.styleAt(si, active.r, active.c);
    const pc = cur.patternColor ?? lastPatternColor;
    const grid = el('div', { class: 'pattern-grid' }, PATTERNS.map(([v, l]) => el('button', {
      class: `pattern-swatch${cur.pattern === v ? ' on' : ''}`, title: l, onmousedown: (e) => e.preventDefault(),
      style: { background: patternCss(v, pc, cur.fill ?? '#ffffff') },
      onclick: () => { closeMenus(); applyStyle({ pattern: v, patternColor: pc }); focusGrid(); },
    })));
    return [
      { sep: true },
      {
        label: '무늬 스타일', icon: 'fill', submenu: [
          { label: '무늬 없음', action: () => applyStyle({ pattern: undefined, patternColor: undefined }) },
          { node: grid },
        ],
      },
      {
        label: '무늬 색', submenu: [
          ...['#000000', '#7f7f7f', '#c00000', '#ff0000', '#ffc000', '#ffff00', '#92d050', '#00b050', '#00b0f0', '#0070c0', '#002060', '#7030a0'].map((c) => ({
            label: c, swatch: c, action: () => { lastPatternColor = c; applyStyle({ patternColor: c, ...(cur.pattern ? {} : { pattern: 'lightGray' }) }); },
          })),
        ],
      },
      { label: '셀 서식 채우기...', action: () => run('formatCells') },
    ];
  })();
  paletteMenu(anchorEl, kind === 'fill' ? '채우기 없음' : '자동', (color) => {
    if (kind === 'fill') { if (color) lastFill = color; applyStyle(color ? { fill: color, gradient: undefined } : { fill: undefined, gradient: undefined, pattern: undefined, patternColor: undefined }); }
    else { if (color) lastFont = color; applyStyle({ color: color || undefined }); }
  }, extra);
}

/** 테마 색 · 표준 색 · 다른 색 팔레트 (onPick(색 | null)) */
function paletteMenu(anchorEl, noneLabel, onPick, extra = []) {
  const pick = (color) => {
    closeMenus();
    onPick(color);
    focusGrid();
  };
  const swatches = (colors, gap) => el('div', { class: `palette-row${gap ? ' gap' : ''}` }, colors.map((c) => el('button', {
    class: 'swatch', type: 'button', title: c, 'aria-label': `색 ${c}`, 'data-color': c, style: { background: c }, onmousedown: (e) => e.preventDefault(), onclick: () => pick(c),
  })));
  const custom = el('input', { type: 'color', tabindex: '-1', 'aria-label': '다른 색', style: { width: '0', height: '0', opacity: '0', position: 'absolute' } });
  custom.addEventListener('change', () => pick(custom.value));
  const rows = themeRows();
  const palette = el('div', { class: 'palette' },
    el('div', { class: 'menu-title', style: { padding: '0 0 4px' } }, '테마 색'),
    rows.map((r, i) => swatches(r, i === 0 || i === rows.length - 1)),
    el('div', { class: 'menu-title', style: { padding: '4px 0' } }, '표준 색'),
    swatches(STANDARD));
  // 엑셀: 글꼴 색은 [자동]이 맨 위, 채우기 색은 [채우기 없음]이 표준 색 아래
  const noneTop = !/^채우기 없음|^색 없음|^없음/.test(noneLabel);
  const menu = openMenu(anchorEl, [
    ...(noneTop ? [{ label: noneLabel, action: () => pick(null) }] : []),
    { node: palette },
    { sep: true },
    ...(noneTop ? [] : [{ label: noneLabel, icon: 'fill', action: () => pick(null) }]),
    { node: el('div', {}, custom) },
    { label: '다른 색...', action: () => custom.click() },
    ...extra,
  ], { scroll: true });
  menu.classList.add('color-palette-menu');
  // 팔레트도 메뉴의 일부다. 행/열 방향키와 Tab으로 색과 하단 명령을 모두 방문한다.
  menu.addEventListener('keydown', (event) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.isComposing) return;
    const controls = [...menu.querySelectorAll('.swatch, :scope > .menu-item:not(:disabled)')];
    const current = controls.indexOf(document.activeElement);
    if (current < 0) return;
    const colors = [...palette.querySelectorAll('.swatch')], index = colors.indexOf(document.activeElement);
    let next = null;
    if (event.key === 'Tab') next = controls[(current + (event.shiftKey ? -1 : 1) + controls.length) % controls.length];
    else if (event.key === 'Home') next = index >= 0 && !event.ctrlKey ? colors[Math.floor(index / 10) * 10] : controls[0];
    else if (event.key === 'End') next = index >= 0 ? colors[Math.min(colors.length - 1, Math.floor(index / 10) * 10 + 9)] : controls.at(-1);
    else if (index >= 0 && ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key)) {
      const step = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -10, ArrowDown: 10 }[event.key];
      const to = index + step;
      const edge = controls.indexOf(step > 0 ? colors.at(-1) : colors[0]) + (step > 0 ? 1 : -1);
      next = colors[to] ?? controls[Math.max(0, Math.min(controls.length - 1, edge))];
    } else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') next = controls[(current + (event.key === 'ArrowDown' ? 1 : -1) + controls.length) % controls.length];
    else if (index >= 0 && (event.key === 'Enter' || event.key === ' ')) {
      event.preventDefault(); event.stopImmediatePropagation(); document.activeElement.click(); return;
    }
    if (next) { event.preventDefault(); event.stopImmediatePropagation(); next.focus(); next.scrollIntoView({ block: 'nearest' }); }
  }, true);
  (noneTop ? menu.querySelector(':scope > .menu-item') : palette.querySelector('.swatch'))?.focus();
}


/** 조건부 서식 견본 모음 (엑셀처럼 작은 견본 격자, 마우스를 올리면 이름) */
function cfGallery(items, add) {
  return el('div', { class: 'cf-gallery' }, items.map((it) => el('button', {
    class: 'cf-swatch', title: it.n, style: { background: it.bg }, onmousedown: (e) => e.preventDefault(),
    onclick: () => { closeMenus(); add(it.rule); focusGrid(); },
  })));
}

