/**
 * 웹 가져오기 함수 (IMPORTXML · IMPORTHTML · GOOGLEFINANCE …) 의 네트워크: 서버가 있으면 /api/fetch 중계, 없으면 브라우저가 직접
 * (CORS 를 허용하지 않는 사이트는 서버 실행(npm start)이 필요). IMPORTRANGE 의 WIXEL 문서는 서버 · 보관함에서 찾음
 */
async function webFetch(url) {
  if (url.startsWith('wixel-doc:')) return wixelRangeCsv(url.slice(10));
  if (server.available) return server.fetchText(url);
  let res;
  try { res = await fetch(url, { cache: 'no-store' }); } catch { throw new Error('이 사이트는 브라우저에서 직접 가져올 수 없습니다 (CORS). WIXEL 서버(npm start)에서 열면 가져올 수 있습니다.'); }
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.text();
}
async function wixelRangeCsv(spec) {
  const [name, sheetName, area] = spec.split('\u0001');
  const denied = privateImportError(`wixel-doc:${spec}`);
  if (denied) throw new Error(denied);
  let data = null;
  if (name === docName) data = { workbook: null, live: wb };
  if (!data && server.connected) { try { data = await server.load(name); } catch { /* 없음 */ } }
  if (!data) {
    const hit = (await libList()).find((d) => d.name === name);
    if (hit) data = await libLoad(hit.id);
  }
  if (!data) throw new Error(`'${name}' 문서를 찾을 수 없습니다`);
  const book = data.live ?? new Workbook(data.workbook ?? data);
  const s = sheetName ? book.sheetIndexByName(sheetName) : 0;
  if (s < 0 || s == null) throw new Error(`'${sheetName}' 시트가 없습니다`);
  const rg = parseRangeName(area.replace(/\$/g, ""));
  if (!rg) throw new Error(`범위 '${area}' 를 읽을 수 없습니다`);
  const rows = [];
  for (let r = rg.r1; r <= Math.min(rg.r2, rg.r1 + 50000); r++) {
    const row = [];
    for (let c = rg.c1; c <= Math.min(rg.c2, rg.c1 + 500); c++) {
      const v = book.getValue(s, r, c);
      const t = v === null || v === undefined ? '' : isError(v) ? v.code : String(v);
      row.push(/[",\n\r]/.test(t) ? `"${t.replace(/"/g, '""')}"` : t);
    }
    rows.push(row.join(','));
  }
  return rows.join('\n');
}
function privateImportError(url) {
  if (!url.startsWith('wixel-doc:') || url.slice(10).split('\u0001')[0] === docName) return null;
  if (viewOnly) return '공개 읽기 전용 문서는 개인 보관함이나 브라우저의 다른 문서를 참조할 수 없습니다.';
  if (!allowPrivateImports) return '다른 WIXEL 문서 참조가 차단되었습니다. 신뢰하는 문서라면 데이터 › 문서 참조 권한에서 현재 세션에 허용하세요.';
  return null;
}
NET.fetcher = webFetch;
NET.authorize = privateImportError;
NET.onDone = (sheets) => {
  if (!wb) return;
  for (const s of sheets) if (s < wb.sheets.length) wb.invalidate(s);
  gv?.renderAll();
};

/** 전역 오류 보호: 명령 하나가 실패해도 앱은 계속 동작하고, 사용자에게는 한국어 안내만 */
let lastErrToast = 0;
function reportError(err, where = '') {
  const msg = String(err?.message ?? err ?? '');
  if (!msg || /ResizeObserver loop|AbortError|The user aborted/i.test(msg)) return;
  console.error(where, err);
  const now = Date.now();
  if (now - lastErrToast < 4000) return;
  lastErrToast = now;
  toast(`${where ? `'${where}' 실행 중 ` : ''}문제가 생겼습니다: ${msg.slice(0, 120)} — 저장 상태를 확인하고 필요한 경우 파일로 저장하세요.`);
}
window.addEventListener('error', (e) => reportError(e.error ?? e.message));
window.addEventListener('unhandledrejection', (e) => reportError(e.reason));

function run(cmd, arg, { keepMenu = false } = {}) {
  if (!keepMenu) closeMenus();
  if (viewOnly && protectAction(cmd) !== 'free' && !VIEW_CMDS.has(cmd)) { toast('읽기 전용으로 게시된 문서입니다. [편집용 사본 만들기]를 누르면 고칠 수 있습니다.'); return; }
  if (editing && !NO_COMMIT.has(cmd)) {
    if (cmd === 'undo') { cancelEdit(); return; }
    if (!commitEdit()) return;
  }
  const fn = COMMANDS[cmd];
  if (!fn) { toast('지원하지 않는 기능입니다.'); return; }
  if (protectBlocked(protectAction(cmd), sel, cmd, () => run(cmd, arg, { keepMenu }))) return;
  if (STRUCT_CMDS.has(cmd) && structureLocked()) return;
  if (wb.props?.markedFinal && protectAction(cmd) !== 'free' && !VIEW_CMDS.has(cmd) && !FINAL_OK.has(cmd)) { finalNotice(); return; }
  try {
    const out = fn(arg);
    if (out && typeof out.catch === 'function') out.catch((err) => reportError(err, cmd));
  } catch (err) {
    reportError(err, cmd);
  }
  if (REPEATABLE.has(cmd)) lastRepeat = () => COMMANDS[cmd](arg);
  if (!keepMenu && !document.activeElement?.closest('.dialog')) focusGrid();
}

function restoreMeta(m) {
  if (m.si !== si && m.si < wb.sheets.length) switchSheet(m.si);
  gv.layout();
  selectRange(m.sel, m.selKind ?? 'cells', m.active);
  gv.ensureVisible(m.active.r, m.active.c);
}

// ───────────────────────── 보기 ─────────────────────────
function applyView() {
  dom.formulaRow.classList.toggle('hidden', !view.showFormulaBar);
  if (!gv) return;
  gv.layout();
  updateSelectionUI();
}

/** 시트를 처음 볼 때: 엑셀에서 저장한 첫 화면(처음 보이는 칸 · 활성 셀), 없으면 맨 위 */
function showSheetStart() {
  const v = sheet().view;
  const f = sheet().freeze;
  if (v) {
    gv.setScroll(Math.max(0, gv.cols.pos(v.left ?? 0) - gv.cols.pos(f?.cols || 0)), Math.max(0, gv.rows.pos(v.top ?? 0) - gv.rows.pos(f?.rows || 0)));
    selectCell(v.r ?? v.top ?? 0, v.c ?? v.left ?? 0, { scroll: false });
  } else {
    gv.setScroll(0, 0);
    selectCell(f?.rows || 0, f?.cols || 0);
  }
}

function fitMobileScreen() {
  if (!mobileWork.active) mobileWork.setPreference('on');
  mobileZooms.delete(sheet()); applySheetZoom();
  const rail = $('ribbon'); rail.scrollLeft = 0;
  gv.layout(); gv.ensureVisible(active.r, active.c);
}
